\label{lem:c11-pullback-isomorphisms}
Let $\mathfrak T$ satisfy Assumption~\ref{ass:c11-deformations}.
For each ${\normalfont{\boldsymbol r}}\in\mathfrak T$, the following assertions hold.
\begin{itemize}
 \item[\normalfont{(i)}] For $-1\leq s\leq1$,
 \begin{equation}
 	\tau_{\normalfont{\boldsymbol r}}\in\mathscr L_{\text{\normalfont iso}}
 	\bigl(H^s(\Gamma_{\normalfont{\boldsymbol r}}),H^s(\widehat\Gamma)\bigr)
 	\quad\text{and}\quad
 	\tau_{\normalfont{\boldsymbol r}}^{-1}\in\mathscr L_{\text{\normalfont iso}}
 	\bigl(H^s(\widehat\Gamma),H^s(\Gamma_{\normalfont{\boldsymbol r}})\bigr).
 \end{equation}
 \item[\normalfont{(ii)}] For $k=0,1$ and $0<\alpha<1$,
 \begin{equation}
 	\tau_{\normalfont{\boldsymbol r}}\in\mathscr L_{\text{\normalfont iso}}
 	\bigl(\mathscr C^{k,\alpha}(\Gamma_{\normalfont{\boldsymbol r}}),
 	      \mathscr C^{k,\alpha}(\widehat\Gamma)\bigr)
 	\quad\text{and}\quad
 	\tau_{\normalfont{\boldsymbol r}}^{-1}\in\mathscr L_{\text{\normalfont iso}}
 	\bigl(\mathscr C^{k,\alpha}(\widehat\Gamma),
 	      \mathscr C^{k,\alpha}(\Gamma_{\normalfont{\boldsymbol r}})\bigr).
 \end{equation}
\end{itemize}

\label{lem:c11-sobolev-extension}
For a given $0<\alpha<1$, let
$\widehat{\mathsf T}\in\mathscr L(\mathscr C^{0,\alpha}(\widehat\Gamma),
\allowbreak\mathscr C^{1,\alpha}(\widehat\Gamma))$ satisfy
\begin{equation}\label{eq:symmetry_Lax}
	\int_{\widehat\Gamma}(\widehat{\mathsf T}u)(\widehat{\mathbf{x}})
	    v(\widehat{\mathbf{x}})\,\,\mathrm d s_{\widehat{\mathbf{x}}}
	=
	\int_{\widehat\Gamma}u(\widehat{\mathbf{x}})
	    (\widehat{\mathsf T}v)(\widehat{\mathbf{x}})\,
	    \,\mathrm d s_{\widehat{\mathbf{x}}},
\end{equation}
for all $u,v\in\mathscr C^{0,\alpha}(\widehat\Gamma)$.
Then the following assertions hold.
\begin{itemize}
 \item[\normalfont{(i)}] The operator $\widehat{\mathsf T}$ has a unique
 bounded extension
 \begin{equation}
 	\mathcal E(\widehat{\mathsf T}):
 	H^{-\frac{1}{2}}(\widehat\Gamma)\to H^{\frac{1}{2}}(\widehat\Gamma).
 \end{equation}
 \item[\normalfont{(ii)}] For operators satisfying \eqref{eq:symmetry_Lax}, the extension
 operation $\mathcal E$ is complex linear and satisfies
 \begin{equation}
 	\|\mathcal E(\widehat{\mathsf T})\|_
 	    {\mathscr L(H^{-\frac{1}{2}}(\widehat\Gamma),
 	                H^{\frac{1}{2}}(\widehat\Gamma))}
 	\leq C
 	\|\widehat{\mathsf T}\|_
 	    {\mathscr L(\mathscr C^{0,\alpha}(\widehat\Gamma),
 	                \mathscr C^{1,\alpha}(\widehat\Gamma))},
 \end{equation}
 where $C=C(\widehat\Gamma,\alpha)$ is given explicitly
 in~\eqref{eq:c11-sobolev-extension-constant}.
 \item[\normalfont{(iii)}] 
For each $u\in\mathscr C^{0,\alpha}(\widehat\Gamma)$, it holds that
 \begin{equation}
 \label{eq:c11-sobolev-extension-agreement}
 	\mathcal E(\widehat{\mathsf T})u=\widehat{\mathsf T}u.
 \end{equation}
\end{itemize}

\label{thm:c11-helmholtz-calderon-holomorphy}
Let $\mathfrak T$ satisfy Assumption~\ref{ass:c11-deformations}.
Then there exists $\delta>0$ such that the maps
\begin{equation}
	\widehat{\mathcal C}^{(\kappa),\pm}
	:\mathfrak T\to
	\mathscr L\Bigl(
	H^{\frac12}(\widehat\Gamma)\times H^{-\frac12}(\widehat\Gamma),
	H^{\frac12}(\widehat\Gamma)\times H^{-\frac12}(\widehat\Gamma)
	\Bigr):{\normalfont{\boldsymbol r}}\mapsto\widehat{\mathsf C}_{\normalfont{\boldsymbol r}}^{(\kappa),\pm}
\end{equation}
admit bounded holomorphic extensions to $\mathfrak T_\delta$.

\label{prop:c11-singlelayer-holomorphy}
Let $\mathfrak T$ satisfy Assumption~\ref{ass:c11-deformations}.
Then there exists $\delta>0$ such that the maps
\begin{equation}
	\mathfrak T\to
	\mathscr L\bigl(H^{-\frac{1}{2}}(\widehat\Gamma),H^{\frac{1}{2}}(\widehat\Gamma)\bigr):
	{\normalfont{\boldsymbol r}}\mapsto\widehat{\mathsf V}_{\normalfont{\boldsymbol r}}^{(\kappa)},
\end{equation}
and
\begin{equation}
	\mathfrak T\to
	\mathscr L\bigl(H^{-\frac{1}{2}}(\widehat\Gamma),H^{\frac{1}{2}}(\widehat\Gamma)\bigr):
	{\normalfont{\boldsymbol r}}\mapsto\widehat{\mathsf U}_{\normalfont{\boldsymbol r}}^{(\kappa)},
\end{equation}
admit bounded holomorphic extensions
to $\mathfrak T_\delta$.

\label{prop:c11-double-layer-holomorphy}
Let $\mathfrak T$ satisfy Assumption~\ref{ass:c11-deformations}.
Then there exists $\delta>0$ such that the map
\begin{equation}
	\mathfrak T\to
	\mathscr L\bigl(H^{\frac12}(\widehat\Gamma),H^{\frac12}(\widehat\Gamma)\bigr):
	{\normalfont{\boldsymbol r}}\mapsto\widehat{\mathsf K}_{\normalfont{\boldsymbol r}}^{(\kappa)},
\end{equation}
admits a bounded holomorphic extension to $\mathfrak T_\delta$.

\label{prop:c11-adjoint-double-layer-holomorphy}
Let $\mathfrak T$ satisfy Assumption~\ref{ass:c11-deformations}.
Then there exists $\delta>0$ such that the map
\begin{equation}
	\widehat{\mathcal K}^{(\kappa)\prime}:
	\mathfrak T\to
	\mathscr L\bigl(H^{-\frac12}(\widehat\Gamma),H^{-\frac12}(\widehat\Gamma)\bigr):
	{\normalfont{\boldsymbol r}}\mapsto\widehat{\mathsf K}_{\normalfont{\boldsymbol r}}^{(\kappa)\prime},
\end{equation}
admits a bounded holomorphic extension to $\mathfrak T_\delta$.

\label{prop:c11-hypersingular-holomorphy}
Let $\mathfrak T$ satisfy Assumption~\ref{ass:c11-deformations}.
Then there exists $\delta>0$ such that the map
\begin{equation}
	\widehat{\mathcal W}^{(\kappa)}:
	\mathfrak T\to
	\mathscr L\bigl(H^{\frac12}(\widehat\Gamma),H^{-\frac12}(\widehat\Gamma)\bigr):
	{\normalfont{\boldsymbol r}}\mapsto\widehat{\mathsf W}_{\normalfont{\boldsymbol r}}^{(\kappa)},
\end{equation}
admits a bounded holomorphic extension to $\mathfrak T_\delta$.

\label{thm:c11-efie-holomorphy}
Let $\mathfrak T$ satisfy Assumption~\ref{ass:c11-deformations}.
Then there exists $\delta>0$ such that the map
\begin{equation}
	\widehat{\mathcal A}^{(\kappa)}:
	\mathfrak T\to\mathscr L(\widehat X,\widehat X'):
	{\normalfont{\boldsymbol r}}\mapsto\widehat{\mathsf A}_{\normalfont{\boldsymbol r}}^{(\kappa)}
\end{equation}
admits a bounded holomorphic extension to $\mathfrak T_\delta$.

\label{ass:c11-nonresonance}
For each ${\normalfont{\boldsymbol r}}\in\mathfrak T$,
$\kappa^2$ is not an interior electric Maxwell eigenvalue of $\text{D}_{\normalfont{\boldsymbol r}}$.
That is, the only $\boldsymbol E\in\boldsymbol H_0(\operatorname{\mathbf{curl}},\text{D}_{\normalfont{\boldsymbol r}})$
satisfying
\begin{equation}
	\int_{\text{D}_{\normalfont{\boldsymbol r}}}\operatorname{\mathbf{curl}}\boldsymbol E(\mathbf{x})\cdot
	    \overline{\operatorname{\mathbf{curl}}\boldsymbol V(\mathbf{x})}\,\,\mathrm d\mathbf{x}
	=\kappa^2\int_{\text{D}_{\normalfont{\boldsymbol r}}}\boldsymbol E(\mathbf{x})\cdot
	    \overline{\boldsymbol V(\mathbf{x})}\,\,\mathrm d\mathbf{x},
	\quad \forall\boldsymbol V\in\boldsymbol H_0(\operatorname{\mathbf{curl}},\text{D}_{\normalfont{\boldsymbol r}}),
\end{equation}
is $\boldsymbol E=0$.

\label{cor:c11-closed-solution-holomorphy}
Let $\mathfrak T$ satisfy
Assumptions~\ref{ass:c11-deformations} and~\ref{ass:c11-nonresonance}.
Then the following assertions hold.
\begin{itemize}
 \item[\normalfont{(i)}] There exists $\delta>0$ such that the map
 \begin{equation}
	\mathfrak T\to\mathscr L(\widehat X',\widehat X):
	{\normalfont{\boldsymbol r}}\mapsto
	(\widehat{\mathsf A}_{\normalfont{\boldsymbol r}}^{(\kappa)})^{-1}
 \end{equation}
 admits a bounded holomorphic extension to $\mathfrak T_\delta$.
 \item[\normalfont{(ii)}] For each ${\normalfont{\boldsymbol r}}\in\mathfrak T$, let
 $\boldsymbol f_{\normalfont{\boldsymbol r}}\in X_{\normalfont{\boldsymbol r}}'$ and assume
 that $\mathfrak T\ni{\normalfont{\boldsymbol r}}\mapsto\widehat{\boldsymbol f}_{\normalfont{\boldsymbol r}}\in\widehat X'$
 admits a bounded holomorphic extension to $\mathfrak T_{\delta_f}$
 for some $\delta_f>0$. For each ${\normalfont{\boldsymbol r}}\in\mathfrak T$, we seek
 $\boldsymbol j_{\normalfont{\boldsymbol r}}\in X_{\normalfont{\boldsymbol r}}$ such that
 \begin{equation}
 	\mathsf A_{\Gamma_{\normalfont{\boldsymbol r}}}^{(\kappa)}\boldsymbol j_{\normalfont{\boldsymbol r}}
	=\boldsymbol f_{\normalfont{\boldsymbol r}}.
 \end{equation}
 This problem is well-posed and there exists $\delta\in(0,\delta_f]$
 such that the map
 \begin{equation}
	\mathfrak T\to\widehat X:{\normalfont{\boldsymbol r}}\mapsto
	\widehat{\boldsymbol j}_{\normalfont{\boldsymbol r}}
	=(\widehat{\mathsf A}_{\normalfont{\boldsymbol r}}^{(\kappa)})^{-1}
	     \widehat{\boldsymbol f}_{\normalfont{\boldsymbol r}}
 \end{equation}
 admits a bounded holomorphic extension to $\mathfrak T_\delta$.
\end{itemize}

\label{lem:c11-screen-scalar-operators}
Let $\mathfrak T$ satisfy
Assumptions~\ref{ass:c11-deformations} and~\ref{ass:c11-screen}.
For each ${\normalfont{\boldsymbol r}}\in\mathfrak T$, the following assertions hold.
\begin{itemize}
 \item[\normalfont{(i)}] For
 $S\in\{\Gamma_{\normalfont{\boldsymbol r}}^s,\widehat\Gamma^s\}$ with supporting boundary
 $\Gamma$, multiplication by $m|_S$, $m\in\mathscr C^{0,1}(\Gamma)$,
 is bounded on $H^{\frac12}(S)$ and
 $\widetilde H^{-\frac12}(S)$, and commutes with restriction
 and extension by zero, respectively.
 \item[\normalfont{(ii)}] The pullbacks
 $\tau_{\normalfont{\boldsymbol r}}^s:H^{\frac12}(\Gamma_{\normalfont{\boldsymbol r}}^s)\to H^{\frac12}(\widehat\Gamma^s)$
 and
 $\tau_{\normalfont{\boldsymbol r}}^s:\widetilde H^{-\frac12}(\Gamma_{\normalfont{\boldsymbol r}}^s)\to
 \widetilde H^{-\frac12}(\widehat\Gamma^s)$
 are bounded isomorphisms with inverse $(\tau_{\normalfont{\boldsymbol r}}^s)^{-1}$.
 They satisfy
 \begin{equation}
	\tau_{\normalfont{\boldsymbol r}}^s\mathsf R_{\normalfont{\boldsymbol r}}^{(D)}
	=\widehat{\mathsf R}^{(D)}\tau_{\normalfont{\boldsymbol r}}
	\quad\text{and}\quad
	\tau_{\normalfont{\boldsymbol r}}\mathsf E_{\normalfont{\boldsymbol r}}^{(N)}
	=\widehat{\mathsf E}^{(N)}\tau_{\normalfont{\boldsymbol r}}^s.
	\label{eq:c11-screen-scalar-transport}
 \end{equation}
\end{itemize}

\label{lem:c11-screen-extension}
Let $\mathfrak T$ satisfy
Assumptions~\ref{ass:c11-deformations} and~\ref{ass:c11-screen}.
For each ${\normalfont{\boldsymbol r}}\in\mathfrak T$, the maps
 \begin{equation}
 	\mathcal P_{\normalfont{\boldsymbol r}}^s\in\mathscr L_{\text{\normalfont iso}}(X_{\normalfont{\boldsymbol r}}^s,\widehat X^s)
 	\quad\text{and}\quad
 	(\mathcal P_{\normalfont{\boldsymbol r}}^s)^{-1}\in\mathscr L_{\text{\normalfont iso}}(\widehat X^s,X_{\normalfont{\boldsymbol r}}^s)
 \end{equation}
 satisfy
 \begin{equation}
 	\widehat{\mathsf E}_X\mathcal P_{\normalfont{\boldsymbol r}}^s
 	=\mathcal P_{\normalfont{\boldsymbol r}}\mathsf E_{{\normalfont{\boldsymbol r}},X}.
 	\label{eq:c11-screen-piola-extension}
 \end{equation}

\label{thm:c11-screen-holomorphy}
Let $\mathfrak T$ satisfy
Assumptions~\ref{ass:c11-deformations} and~\ref{ass:c11-screen}.
Then there exists $\delta>0$ such that the map
\begin{equation}
	\widehat{\mathcal A}_s^{(\kappa)}:
	\mathfrak T\to\mathscr L(\widehat X^s,\widehat X^{s\prime}):
	{\normalfont{\boldsymbol r}}\mapsto\widehat{\mathsf A}_{{\normalfont{\boldsymbol r}},s}^{(\kappa)}
\end{equation}
admits a bounded holomorphic extension to $\mathfrak T_\delta$.

\label{cor:c11-screen-solution-holomorphy}
Let $\mathfrak T$ satisfy
Assumptions~\ref{ass:c11-deformations} and~\ref{ass:c11-screen}.
Then the following assertions hold.
\begin{itemize}
 \item[\normalfont{(i)}] There exists $\delta>0$ such that the map
 \begin{equation}
 	\mathfrak T\to\mathscr L(\widehat X^{s\prime},\widehat X^s):
 	{\normalfont{\boldsymbol r}}\mapsto(\widehat{\mathsf A}_{{\normalfont{\boldsymbol r}},s}^{(\kappa)})^{-1}
 \end{equation}
 admits a bounded holomorphic extension to $\mathfrak T_\delta$.
 \item[\normalfont{(ii)}] For each ${\normalfont{\boldsymbol r}}\in\mathfrak T$, let
 $\boldsymbol f_{\normalfont{\boldsymbol r}}^s\in X_{\normalfont{\boldsymbol r}}^{s\prime}$
 and assume that $\mathfrak T\ni{\normalfont{\boldsymbol r}}\mapsto\widehat{\boldsymbol f}_{\normalfont{\boldsymbol r}}^s
 \in\widehat X^{s\prime}$ admits a bounded holomorphic extension to
 $\mathfrak T_{\delta_f}$ for some $\delta_f>0$.
 For each ${\normalfont{\boldsymbol r}}\in\mathfrak T$, we seek
 $\boldsymbol j_{\normalfont{\boldsymbol r}}^s\in X_{\normalfont{\boldsymbol r}}^s$ such that
 \begin{equation}
 	\mathsf A_{\Gamma_{\normalfont{\boldsymbol r}}^s}^{(\kappa)}\boldsymbol j_{\normalfont{\boldsymbol r}}^s
	=\boldsymbol f_{\normalfont{\boldsymbol r}}^s.
 \end{equation}
 This problem is well-posed. There exists
 $\delta\in(0,\delta_f]$ such that the map
 \begin{equation}
 	\mathfrak T\to\widehat X^s:{\normalfont{\boldsymbol r}}\mapsto\widehat{\boldsymbol j}_{\normalfont{\boldsymbol r}}^s
 	=(\widehat{\mathsf A}_{{\normalfont{\boldsymbol r}},s}^{(\kappa)})^{-1}
 	     \widehat{\boldsymbol f}_{\normalfont{\boldsymbol r}}^s
 \end{equation}
 admits a bounded holomorphic extension to $\mathfrak T_\delta$.
\end{itemize}

The bounded isomorphism
$\mathsf A_{\Gamma_{\normalfont{\boldsymbol r}}^s}^{(\kappa)}:X_{\normalfont{\boldsymbol r}}^s\to X_{\normalfont{\boldsymbol r}}^{s\prime}$
from \cite[Corollary~3.6]{BuffaChristiansen2003} and
Lemma~\ref{lem:c11-screen-extension} imply that
$\widehat{\mathsf A}_{{\normalfont{\boldsymbol r}},s}^{(\kappa)}$ is boundedly invertible for each
${\normalfont{\boldsymbol r}}\in\mathfrak T$.
Theorem~\ref{thm:c11-screen-holomorphy} and the compactness and
holomorphic inversion argument used in the proof of
Corollary~\ref{cor:c11-closed-solution-holomorphy}
\cite[Proposition~4.20, items~(i) and~(ii)]{HS21}
give item~(i), with
\begin{equation}
	M_{\delta,s}\coloneqq\sup_{{\normalfont{\boldsymbol r}}\in\mathfrak T_\delta}
	\|(\widehat{\mathsf A}_{{\normalfont{\boldsymbol r}},s}^{(\kappa)})^{-1}\|_
	      {\mathscr L(\widehat X^{s\prime},\widehat X^s)}<\infty.
\end{equation}
For item~(ii), choose $\delta\leq\delta_f$ within the inverse extension
neighborhood. As in that proof, the bounded bilinear evaluation
$\mathscr L(\widehat X^{s\prime},\widehat X^s)\times
\widehat X^{s\prime}\to\widehat X^s$ gives the asserted bounded
holomorphic solution map
\cite[Proposition~4.20, item~(iii)]{HS21}, with
\begin{equation}
	\sup_{{\normalfont{\boldsymbol r}}\in\mathfrak T_\delta}
	      \|\widehat{\boldsymbol j}_{\normalfont{\boldsymbol r}}^s\|_{\widehat X^s}
	\leq M_{\delta,s}\sup_{{\normalfont{\boldsymbol r}}\in\mathfrak T_\delta}
	      \|\widehat{\boldsymbol f}_{\normalfont{\boldsymbol r}}^s\|_{\widehat X^{s\prime}}
	<\infty.\qedhere
\end{equation}

\label{thm:c11-operator-extension}
Let $X$ and $Y$ be complex normed spaces with inner products
$(\cdot,\cdot)_X$ and $(\cdot,\cdot)_Y$. Let
$\|u\|_{X,0}\coloneqq(u,u)_X^{1/2}$ and
$\|v\|_{Y,0}\coloneqq(v,v)_Y^{1/2}$, and assume that
\begin{equation}
	\|u\|_{X,0}\leq c_X\|u\|_X
	\quad\text{and}\quad
	\|v\|_{Y,0}\leq c_Y\|v\|_Y,
	\quad\forall u\in X,\ \forall v\in Y,
\end{equation}
for some $c_X,c_Y>0$.
Suppose that $A\in\mathscr L(X,Y)$ and
$B\in\mathscr L(Y,X)$ satisfy
\begin{equation}
	(Au,v)_Y=(u,Bv)_X,
	\quad\forall u\in X,\ \forall v\in Y.
\end{equation}
Then
\begin{equation}
	\|Au\|_{Y,0}^2
	\leq\|A\|_{\mathscr L(X,Y)}
	     \|B\|_{\mathscr L(Y,X)}\|u\|_{X,0}^2,
	\quad\forall u\in X.
\end{equation}
Consequently, $A$ has a unique bounded extension between the
Hilbert completions of $X$ and $Y$ in their inner product norms,
with operator norm at most
$\bigl(\|A\|_{\mathscr L(X,Y)}
\|B\|_{\mathscr L(Y,X)}\bigr)^{1/2}$.
